"""Validation rules migrated from legacy/opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


_EMPTY_VALUES = ("", None)
_DATE_SENTINEL = "00000000"


def _value(image: dict[str, Any] | None, column: str) -> Any:
    if image is None:
        return ""
    value = image.get(column, "")
    return "" if value is None else value


def _nvl(value: Any, default: Any) -> Any:
    return default if value in _EMPTY_VALUES else value


def _number(value: Any) -> Decimal:
    if value in _EMPTY_VALUES:
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _date_gte(left: Any, right: Any) -> bool:
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)
    if left_text == _DATE_SENTINEL or right_text == _DATE_SENTINEL:
        return False
    return left_text >= right_text


def _failure(
    code: str,
    message: str,
    severity: str = "BLOCK",
) -> dict[str, str]:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate applicable opportunity rules in legacy rule-file order."""
    errors: list[dict] = []

    amt = _value(record, "AMT")
    stat_cd = _value(record, "STAT_CD")
    lost_rsn = _value(record, "LOST_RSN")
    close_dt = _value(record, "CLOSE_DT")
    stage_pct = _value(record, "STAGE_PCT")

    # OPP-001
    if event in ("INSERT", "UPDATE"):
        if not (_number(_nvl(amt, 0)) >= Decimal(0)):
            errors.append(_failure("E3001", "Amount negative"))

    # OPP-002
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and _number(_nvl(amt, 0)) == Decimal(0))):
            errors.append(
                _failure("E3002", "Won opportunity requires amount")
            )

    # OPP-003
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "L" and lost_rsn == "")):
            errors.append(_failure("E3003", "Lost reason required"))

    # OPP-004
    if event in ("INSERT", "UPDATE"):
        if not (not (stat_cd == "W" and close_dt == _DATE_SENTINEL)):
            errors.append(
                _failure("E3004", "Won opportunity requires close date")
            )

    # OPP-005
    if event == "UPDATE":
        old_stat_cd = _value(old, "STAT_CD")
        if not (not (old_stat_cd == "W" and stat_cd != "W")):
            errors.append(
                _failure("E3005", "Cannot reopen a won opportunity")
            )

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        stage_number = _number(stage_pct)
        valid_stage = (
            (stat_cd == "P" and stage_number == Decimal(10))
            or (stat_cd == "Q" and stage_number == Decimal(25))
            or (stat_cd == "N" and stage_number == Decimal(60))
            or (stat_cd == "W" and stage_number == Decimal(100))
            or (stat_cd == "L" and stage_number == Decimal(0))
        )
        if not valid_stage:
            errors.append(
                _failure("E3006", "Stage percent inconsistent with status")
            )

    # OPP-007
    if event == "INSERT":
        valid_close_date = (
            close_dt == _DATE_SENTINEL
            or _date_gte(close_dt, today)
        )
        if not valid_close_date:
            errors.append(
                _failure("E3007", "Close date in past", "WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
